using MySqlConnector;
using System.Windows;
using System.Windows.Controls;
namespace WoWItemEditor;
internal sealed record QuestReference(int Id,string Name,string Detail="");
internal static class QuestReferences
{
    internal static async Task<List<QuestReference>> Search(string kind,string search,CatalogResult catalog)
    {
        if(kind=="Item")return catalog.Items.Where(i=>CatalogSearch.Item(i,search)).Select(i=>new QuestReference(i.Id,i.Name,i.SubtypeName)).ToList();
        string? table=kind switch{"Spell"=>"SpellName","Faction"=>"Faction","Skill"=>"SkillLine","Emote"=>"Emotes","Category"=>"QuestInfo","Zone"=>"AreaTable","Trigger"=>"AreaTrigger","Race"=>"ChrRaces",_=>null};
        if(table is not null){var rows=await ItemModelAssets.Shared.Table(table);return rows.Select(p=>new QuestReference(p.Key,Name(p.Value,kind,p.Key),kind=="Trigger"?$"Map {p.Value.GetValueOrDefault("ContinentID")} · {p.Value.GetValueOrDefault("Pos1")}, {p.Value.GetValueOrDefault("Pos2")}, {p.Value.GetValueOrDefault("Pos3")}":"")).Where(r=>CatalogSearch.Matches(search,$"{r.Id} {r.Name} {r.Detail}")).OrderByDescending(r=>int.TryParse(search,out int exact)&&r.Id==exact).ThenBy(r=>r.Name).Take(300).ToList();}
        string sql=kind switch{"Creature"=>"SELECT entry AS Id,name AS Name,CONCAT('Level ',minlevel,'-',maxlevel) AS Detail FROM {0}.creature_template WHERE (name LIKE @term OR entry=@id)","Questgiver"=>"SELECT c.entry AS Id,c.name AS Name,CONCAT('Level ',c.minlevel,'-',c.maxlevel) AS Detail FROM {0}.creature_template c WHERE (c.name LIKE @term OR c.entry=@id) AND "+QuestCreation.EligibleSql,"Object"=>"SELECT entry AS Id,name AS Name,CONCAT('Object type ',type) AS Detail FROM {0}.gameobject_template WHERE (name LIKE @term OR entry=@id)","Quest"=>"SELECT ID AS Id,LogTitle AS Name,CONCAT('Level ',QuestLevel) AS Detail FROM {0}.quest_template WHERE (LogTitle LIKE @term OR ID=@id)",_=>throw new InvalidOperationException("Unsupported reference type.")};
        using var db=await DatabaseConnection.OpenAsync(QuestCreation.World);using var cmd=new MySqlCommand(string.Format(System.Globalization.CultureInfo.InvariantCulture,sql,QuestCreation.World)+" ORDER BY Id=@id DESC,Name LIMIT 200",db);cmd.Parameters.AddWithValue("@term","%"+search+"%");cmd.Parameters.AddWithValue("@id",int.TryParse(search,out int id)?id:0);var result=new List<QuestReference>();using var reader=await cmd.ExecuteReaderAsync();while(await reader.ReadAsync())result.Add(new(reader.GetInt32(0),reader.IsDBNull(1)?"Unnamed":reader.GetString(1),reader.GetString(2)));return result;
    }
    private static string Name(Dictionary<string,string> row,string kind,int id)=>new[]{"Name_lang","Name","DisplayName","AreaName","ZoneName","EmoteSlashCommand","Description"}.Select(k=>row.GetValueOrDefault(k)).FirstOrDefault(v=>!string.IsNullOrWhiteSpace(v))??$"{kind} {id}";
    internal static async Task<string> Label(string kind,int id,CatalogResult catalog){if(id==0)return "None";if(kind=="Item")return catalog.Items.FirstOrDefault(i=>i.Id==id)?.Name??$"Missing item {id}";try{return(await Search(kind,id.ToString(),catalog)).FirstOrDefault(r=>r.Id==id)?.Name??$"{kind} {id}";}catch{return $"{kind} {id} (name unavailable)";}}
    internal static async Task<QuestNpcSource> PreviewNpc(int id){using var db=await DatabaseConnection.OpenAsync(QuestCreation.World);var row=(await WorldDrops.Query(db,null,$"SELECT * FROM {QuestCreation.World}.creature_template WHERE entry={id}")).Single();int N(string key)=>int.Parse(row[key]!);return new(new(id,row["name"]!,N("minlevel"),N("maxlevel"),N("faction")),row,await WorldDrops.Query(db,null,$"SELECT * FROM {QuestCreation.World}.creature_template_model WHERE CreatureID={id} ORDER BY Idx"),await WorldDrops.Query(db,null,$"SELECT * FROM {QuestCreation.World}.creature_equip_template WHERE CreatureID={id} ORDER BY ID"));}
}
internal sealed class QuestReferencePicker : Window
{
    private readonly DataGrid grid=DesignerWindow.Table(("Name","Name"),("ID","Id"),("Details","Detail"));private readonly TextBox search=new();private readonly TextBlock feedback=DesignerWindow.Text("",12);private readonly Button select=new(){Content="Use selected",IsEnabled=false};private readonly ItemModelView model=new(compact:true);private readonly StackPanel tooltip=new();private readonly CatalogResult catalog;private readonly string kind;private readonly QuestItemFilter? itemFilter;private int request,preview;
    internal QuestReference? Selected {get;private set;}
    internal QuestReferencePicker(string kind,CatalogResult catalog){this.kind=kind;this.catalog=catalog;Title="Choose "+kind;Width=1250;Height=850;MinWidth=950;MinHeight=650;Background=TooltipView.Brush("#232428");WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(20)};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(DesignerWindow.Text("Search by name or ID",13));top.Children.Add(search);if(kind=="Item"){itemFilter=new(catalog.Tooltips);top.Children.Add(itemFilter);itemFilter.Changed+=()=>_ = Filter();}top.Children.Add(feedback);var bottom=new WrapPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);bottom.Children.Add(select);DesignerWindow.Button("Cancel",bottom).Click+=(_,_)=>Close();var columns=new Grid();columns.ColumnDefinitions.Add(new());columns.ColumnDefinitions.Add(new());root.Children.Add(columns);columns.Children.Add(grid);UIElement right=kind=="Item"?DesignerWindow.Preview(tooltip,"ITEM PREVIEW"):model;Grid.SetColumn(right,1);columns.Children.Add(right);search.TextChanged+=async(_,_)=>await Filter();grid.SelectionChanged+=async(_,_)=>await Preview();select.Click+=(_,_)=>{Selected=grid.SelectedItem as QuestReference;if(Selected is not null)DialogResult=true;};Loaded+=async(_,_)=>await Filter();Closing+=(_,_)=>{request++;preview++;};}
    private async Task Filter(){int token=++request;feedback.Text="Searching…";try{await Task.Delay(180);if(token!=request)return;var rows=await QuestReferences.Search(kind,search.Text.Trim(),catalog);if(token!=request)return;if(itemFilter is not null){var lookup=catalog.Items.ToDictionary(i=>i.Id);rows=rows.Where(r=>lookup.TryGetValue(r.Id,out var item)&&itemFilter.Matches(item)).ToList();}grid.ItemsSource=rows;feedback.Text=$"{rows.Count} matches"+(kind=="Item"?"":" · narrow your search if the list reaches its limit");}catch(Exception ex){if(token==request)feedback.Text=ex.Message;}}
    private async Task Preview(){int token=++preview;select.IsEnabled=false;if(grid.SelectedItem is not QuestReference row)return;try{if(kind=="Item"){var item=catalog.Items.First(i=>i.Id==row.Id);TooltipView.Fill(tooltip,ItemTooltip.Build(item,catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id)));}else if(kind is "Creature" or "Questgiver"){model.ShowLoading("Loading NPC model…");var source=await QuestReferences.PreviewNpc(row.Id);var scenes=await Task.Run(()=>NpcModelBuilder.Build(source,catalog));if(token!=preview)return;model.ShowScene(scenes[0].Mesh,scenes[0].Name);}else model.ShowLoading(row.Name+"\n"+row.Detail);if(token==preview)select.IsEnabled=true;}catch(Exception ex){if(token==preview){model.ShowLoading("Preview unavailable: "+ex.Message);select.IsEnabled=kind!="Questgiver";if(kind=="Questgiver"){var rows=grid.ItemsSource.Cast<QuestReference>().Where(r=>r.Id!=row.Id).ToArray();grid.ItemsSource=rows;}}}}
}
internal sealed class QuestReferenceField : DockPanel
{
    private readonly TextBlock label=DesignerWindow.Text("None",12);private readonly CatalogResult catalog;internal string Kind {get;set;}internal int Id {get;private set;}internal event Action? Changed;
    internal QuestReferenceField(string kind,CatalogResult catalog){Kind=kind;this.catalog=catalog;LastChildFill=true;var buttons=new WrapPanel();DockPanel.SetDock(buttons,Dock.Right);Children.Add(buttons);DesignerWindow.Button("Choose…",buttons).Click+=async(_,_)=>{var picker=new QuestReferencePicker(Kind,catalog){Owner=Window.GetWindow(this)};if(picker.ShowDialog()==true&&picker.Selected is {} selected)await Set(selected.Id);};DesignerWindow.Button("Clear",buttons).Click+=async(_,_)=>await Set(0);label.TextWrapping=TextWrapping.Wrap;label.VerticalAlignment=VerticalAlignment.Center;Children.Add(label);}
    internal async Task Set(int id){Id=id;label.Text=id==0?"None":"Loading…";label.Text=await QuestReferences.Label(Kind,id,catalog)+(id==0?"":$" ({id})");Changed?.Invoke();}
}
